-- Exact reviewed-source snapshots and corrected candidates; no source/attempt/result rewrite.
create table private.ielts_legacy_cleanup_versions (
 code text not null,revision text not null,material_type text not null,material_id text not null,
 disposition text not null check(disposition in ('revise','retire')),revision_sha256 text not null,
 source_snapshot jsonb not null,revision_payload jsonb not null,created_at timestamptz not null default now(),
 primary key(code,revision),unique(material_type,material_id,revision),
 check(revision_payload->>'code'=code),check(revision_payload->>'revision'=revision),
 check(revision_payload->>'disposition'=disposition),check(revision_payload->'human_approval'='null'::jsonb)
);
alter table private.ielts_legacy_cleanup_versions enable row level security;
revoke all on private.ielts_legacy_cleanup_versions from public,anon,authenticated,service_role;
create trigger preserve_legacy_cleanup before update or delete on private.ielts_legacy_cleanup_versions for each row execute function private.ielts_learning_immutable();
create function private.ielts_cleanup_authorize() returns void language plpgsql security definer set search_path='' as $$
begin
 perform private.ielts_originality_authorize('ielts_reading_set');
 if exists(select 1 from public.users where id=auth.uid() and banned_until>now()) then raise exception 'forbidden';end if;
end; $$;
create function public.rpc_ielts_legacy_cleanup_list() returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 perform private.ielts_cleanup_authorize();
 return (select coalesce(jsonb_agg(x order by x.code),'[]') from (
 select code,revision,disposition,revision_sha256,revision_payload->'content'->>'title' title,split_part(material_type,'_',2) skill,revision_payload->'changes' changes,revision_payload->'blockers' blockers,revision_payload->>'consolidate_into' consolidate_into
 from private.ielts_legacy_cleanup_versions order by code,revision desc limit 100)x);
end; $$;
create function public.rpc_ielts_legacy_cleanup_detail(p_code text,p_revision text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 perform private.ielts_cleanup_authorize();
 select revision_payload into result from private.ielts_legacy_cleanup_versions where code=p_code and revision=p_revision;
 if result is null then raise exception 'revision_not_found';end if;return result;
end; $$;
revoke all on function private.ielts_cleanup_authorize() from public,anon,authenticated,service_role;
revoke all on function public.rpc_ielts_legacy_cleanup_list() from public,anon,authenticated,service_role;
revoke all on function public.rpc_ielts_legacy_cleanup_detail(text,text) from public,anon,authenticated,service_role;
grant execute on function public.rpc_ielts_legacy_cleanup_list(),public.rpc_ielts_legacy_cleanup_detail(text,text) to authenticated;
do $seed$ declare source jsonb; candidate jsonb:=$payload${"code": "L-005", "disposition": "revise", "revision": "2026-10-15.1", "content": {"skill": "listening", "title": "Registering for an evening workshop", "scope": "Guided form-completion practice; fictional dialogue, not an exam paper", "instructions": "Read all questions first. Write ONE WORD AND/OR A NUMBER for each answer. The teacher controls pauses and replays. Record any help used.", "script": "Receptionist: Hello, Westfield Centre. How can I help?\nCaller: I'd like to join the evening workshop. Is it painting?\nReceptionist: The painting group is full. The workshop with places available is pottery.\nCaller: That sounds good. Which day is it?\nReceptionist: Thursday. We used to meet on Tuesday, but the tutor changed the day.\nCaller: And what time should I arrive?\nReceptionist: Please arrive at 6:15. The class starts fifteen minutes later.\nCaller: How much does it cost?\nReceptionist: Eighteen pounds for one session. That includes the materials.\nCaller: Do I need to bring anything?\nReceptionist: Bring an apron to protect your clothes. We provide the tools.\nCaller: Where is the room?\nReceptionist: It is beside the library, through the blue door.\nCaller: Thanks. I'll book one place.", "audio": null, "questions": [{"n": 1, "type": "fill_blank", "question": "Workshop subject: ____", "key": ["pottery"], "evidence": "Receptionist: The workshop with places available is pottery."}, {"n": 2, "type": "fill_blank", "question": "Day: ____", "key": ["Thursday"], "evidence": "Receptionist: Thursday."}, {"n": 3, "type": "fill_blank", "question": "Arrival time: ____", "key": ["6:15", "6.15"], "evidence": "Receptionist: Please arrive at 6:15."}, {"n": 4, "type": "fill_blank", "question": "Price per session: £____", "key": ["18"], "evidence": "Receptionist: Eighteen pounds for one session."}, {"n": 5, "type": "fill_blank", "question": "Bring an ____", "key": ["apron"], "evidence": "Receptionist: Bring an apron to protect your clothes."}, {"n": 6, "type": "fill_blank", "question": "The room is beside the ____", "key": ["library"], "evidence": "Receptionist: It is beside the library, through the blue door."}], "audio_production": {"status": "recording_required", "instruction_voice": "Separate from dialogue", "pre_read_seconds": 30, "finish_seconds": 15, "notice": "Use the existing approved IELTS audio production policy; no legacy recording is approved by this draft."}, "authorship": "Brains Heist AI-assisted revision; human review pending", "sources": []}, "changes": ["Replaced incomplete or unverified source with an original script and aligned questions", "Added answer evidence and explicit word/number limits", "Removed old unverified audio from the revised candidate"], "blockers": ["Produce recording under the approved IELTS audio policy", "Human listening against exact recording/script/keys", "Rights and originality review", "Measured timing, audio hash and device/resume delivery checks"], "material_type": "ielts_listening_set", "material_id": "2", "source_snapshot": {"id": 2, "slug": "ielts-listening-sample-task-1-form-completion", "level": "beginner", "title": "IELTS Listening Sample Task 1 (Form Completion)", "audio_url": "https://sozodkxwhubespiedgxm.supabase.co/storage/v1/object/public/ielts-audio/ielts-listening-sample-task-1-form-completion.mp3", "is_active": true, "questions": null, "created_at": "2026-01-19T12:41:12.629655+00:00", "description": "Sample listening task focused on form completion (Task 1).", "display_code": "L-005", "est_band_max": 6, "est_band_min": 4.5, "instructions": null, "required_tier": "free", "section_label": null, "example_answer": null, "example_prompt": null, "duration_minutes": 10, "originality_label": null, "question_range_label": null}, "review_status": "pending_human_review", "human_approval": null, "revision_sha256": "b7a38798a53c19913da6130c2f9fdcf9d06868812cffb46dffba033c55948e3d"}$payload$::jsonb; begin
