do $seed$ declare source jsonb; candidate jsonb:=$payload${"code": "L-006", "disposition": "revise", "revision": "2026-10-15.1", "content": {"skill": "listening", "title": "Planning a museum visit", "scope": "Guided form-completion practice; fictional dialogue, not an exam paper", "instructions": "Read all questions first. Write ONE WORD AND/OR A NUMBER for each answer. The teacher controls pauses and replays. Record any help used.", "script": "Visitor: I'm organising a visit for our study group. Can we come on Friday?\nAssistant: Friday is fully booked, but we can welcome you on Saturday.\nVisitor: Saturday is fine. There will be sixteen students.\nAssistant: Thank you. Please arrive at 10:20. Your guide will meet you ten minutes later.\nVisitor: What is the price for each student?\nAssistant: Seven pounds. The normal price is nine pounds, but groups pay less.\nVisitor: Where should we meet the guide?\nAssistant: At the side entrance, beside the garden. The main entrance is busy at that time.\nVisitor: Can we leave our bags somewhere?\nAssistant: Yes, there are lockers. Bring a coin to use one; you get it back afterwards.\nVisitor: Is there a café?\nAssistant: Yes, but it closes early that day. We suggest bringing lunch.\nVisitor: Great. I'll send you the group details.", "audio": null, "questions": [{"n": 1, "type": "fill_blank", "question": "Visit day: ____", "key": ["Saturday"], "evidence": "Assistant: we can welcome you on Saturday."}, {"n": 2, "type": "fill_blank", "question": "Number of students: ____", "key": ["16"], "evidence": "Visitor: There will be sixteen students."}, {"n": 3, "type": "fill_blank", "question": "Arrival time: ____", "key": ["10:20", "10.20"], "evidence": "Assistant: Please arrive at 10:20."}, {"n": 4, "type": "fill_blank", "question": "Group price per student: £____", "key": ["7"], "evidence": "Assistant: Seven pounds."}, {"n": 5, "type": "fill_blank", "question": "Meet at the entrance beside the ____", "key": ["garden"], "evidence": "As