do $seed$ declare source jsonb; candidate jsonb:=$payload${"code": "L-010", "disposition": "revise", "revision": "2026-10-15.1", "content": {"skill": "listening", "title": "Booking a guided cycling trip", "scope": "Guided form-completion practice; fictional dialogue, not an exam paper", "instructions": "Read all questions first. Write ONE WORD AND/OR A NUMBER for each answer. The teacher controls pauses and replays. Record any help used.", "script": "Customer: I'd like to book a family cycling trip. Does the route go through the forest?\nOrganiser: We have changed it this month. The guided route now follows the river.\nCustomer: Is it suitable for beginners?\nOrganiser: Yes. There are no steep hills, and the guide stops regularly.\nCustomer: Where do we meet?\nOrganiser: Outside the station. Please use the square in front, not the car park behind it.\nCustomer: What time?\nOrganiser: Nine forty-five. We leave at ten.\nCustomer: Do you provide bikes?\nOrganiser: Yes, and each rider also receives a helmet. Please wear it throughout the trip.\nCustomer: Should we bring food?\nOrganiser: Bring a picnic. There is a planned lunch stop, but no café on this route.\nCustomer: How much is the family ticket?\nOrganiser: Forty-six pounds for two adults and two children. Bike hire is included.\nCustomer: Thank you. I'll book that.", "audio": null, "questions": [{"n": 1, "type": "fill_blank", "question": "The route follows the ____.", "key": ["river"], "evidence": "Organiser: The guided route now follows the river."}, {"n": 2, "type": "fill_blank", "question": "Meeting place: outside the ____.", "key": ["station"], "evidence": "Organiser: Outside the station."}, {"n": 3, "type": "fill_blank", "question": "Meeting time: ____.", "key": ["9:45", "9.45"], "evidence": "Organiser: Nine forty-five."}, {"n": 4, "type": "fill_blank", "question": "Each rider receives a bike and a ____.", "key": ["helmet"], "evidence": "Organiser: each rider also receives a helmet."}, {"n": 5, "type": "fill_blank", "question": "Bring a ____ for lunch.", "key": ["picnic"], "evidence": "Organiser: Bring a picnic."}, {"n": 6, "type": "fill_blank", "question": "Family ticket: £____.", "key": ["46"], "evidence": "Organiser: Forty-six pounds for two adults and two children."}], "audio_production": {"status": "recording_required", "instruction_voice": "Separate from dialogue", "pre_read_seconds": 30, "finish_seconds": 15, "notice": "Use the existing approved IELTS audio production policy; no legacy recording is approved by this draft."}, "authorship": "Brains Heist AI-assisted revision; human review pending", "sources": []}, "changes": ["Replaced incomplete or unverified source with an original script and aligned questions", "Added answer evidence and explicit word/number limits", "Removed old unverified audio from the revised candidate"], "blockers": ["Produce recording under the approved IELTS audio policy", "Human listening against exact recording/script/keys", "Rights and originality review", "Measured timing, audio hash and device/resume delivery checks"], "material_type": "ielts_listening_set", "material_id": "26", "source_snapshot": {"id": 26, "slug": "family-excursions", "level": "B2", "title": "Family Excursions", "audio_url": "https://sozodkxwhubespiedgxm.supabase.co/storage/v1/object/public/ielts-audio/Test%205%20Section%201.mp3", "is_active": true, "questions": [{"id": 40, "body": "Can take photos of the _________ that surround the lake", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["mountains", "Mountains"], "question_order": 1}, {"id": 41, "body": "Farm visit:\nchildren can help feed the sheep\nVisit can include a 40-minute ride on a __________", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["horse", "Horse"], "question_order": 2}, {"id": 42, "body": "Visitors can walk in the farm's ___________ by the lake", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["garden", "gardens", "Garden", "Gardens"], "question_order": 3}, {"id": 43, "body": "___________ is available at extra cost", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["Lunch", "lunch"], "question_order": 4}, {"id": 44, "body": "Cycling trips\nCyclists explore the Back Road\nA ___________ is provided", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["Map", "map"], "question_order": 5}, {"id": 45, "body": "Only suitable for cyclists who have some ___________", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["experience", "Experience"], "question_order": 6}, {"id": 46, "body": "Bikes can be hired from ___________ (near the Cruise Ship Terminal)", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["Ratchesons"], "question_order": 7}, {"id": 47, "body": "Cyclists need:\na repair kit\nfood and drink\na ___________ (can be hired)", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["Helmet", "helmet"], "question_order": 8}, {"id": 48, "body": "There are no ___________ or accommodation in the area\nCost", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["Shops", "shops"], "question_order": 9}, {"id": 49, "body": "Total cost for whole family of cruise and farm visit: $___________", "set_id": 26, "options": null, "explanation": null, "question_type": "fill_blank", "correct_answer": ["267"], "question_order": 10}], "created_at": "2026-05-24T14:12:11.978203+00:00", "description": "Section 1", "display_code": "L-010", "est_band_max": null, "est_band_min": null, "instructions": "Answer while listening ", "required_tier": "free", "section_label": "Write ONE WORD AND/OR A NUMBER for each answer", "example_answer": "steamship", "example_prompt": "Travel on an old", "duration_minutes": 9, "originality_label": null, "question_range_label": "1-10"}, "review_status": "pending_human_review", "human_approval": null, "revision_sha256": "60b8275586c2fae92f8bfc5a3de10c4d356d7b4821a12d9e4d198e25411bc2f2"}$payload$::jsonb; begin
