do $seed$ declare source jsonb; candidate jsonb:=$payload${"code": "W-003", "revision": "2026-10-15.1", "disposition": "retire", "content": null, "changes": ["Duplicate population dataset and prompt with incomplete sample"], "consolidate_into": "W-009", "blockers": ["Retired from future assignment; original history preserved"], "material_type": "ielts_writing_task", "material_id": "1", "source_snapshot": {"id": 1, "slug": "bar-chart-population", "title": "Population Changes Bar Chart", "prompt": "The bar chart below shows population changes in three cities between 2000 and 2020.\r\n\r\nSummarize the information by selecting and reporting the main features, and make comparisons where relevant.\r\n\r\nWrite at least 150 words.\r\n\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\nPOPULATION OF THREE CITIES (in millions)\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\n\r\nCity          │  2000   │  2010   │  2020\r\n──────────────┼─────────┼─────────┼─────────\r\nMetro City    │   2.1   │   3.4   │   5.2\r\nRiverside     │   1.8   │   2.0   │   1.9\r\nOldtown       │   3.5   │   3.2   │   2.8\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\n\r\nBar Chart Visualization:\r\n\r\nMetro City:  2000 ████████████ 2.1M\r\n             2010 ████████████████████ 3.4M\r\n             2020 ██████████████████████████████ 5.2M\r\n\r\nRiverside:   2000 ██████████ 1.8M\r\n             2010 ███████████ 2.0M\r\n             2020 ██████████ 1.9M\r\n\r\nOldtown:     2000 ████████████████████ 3.5M\r\n             2010 ██████████████████ 3.2M\r\n             2020 ████████████████ 2.8M", "is_active": true, "task_type": "task1", "created_at": "2025-11-17T16:32:23.268633+00:00", "bands_target": "5.0-7.0", "display_code": "W-003", "required_tier": "prime_prep_user", "sample_answer": "The bar chart illustrates population changes across three cities over a twenty-year period...", "originality_label": null}, "review_status": "retired_from_future_assignment", "hu