do $seed$ declare source jsonb; candidate jsonb:=$payload${"code": "W-006", "disposition": "revise", "revision": "2026-10-15.1", "content": {"skill": "writing", "title": "Internet Usage by Age Group", "scope": "Writing practice; example response is not a band guarantee", "test_type": "academic", "task_number": 1, "minimum_words": 150, "suggested_minutes": 20, "prompt": "The bar chart below shows the percentage of adults who used the internet daily in five different age groups in 2010 and 2020.\n\nSummarize the information by selecting and reporting the main features, and make comparisons where relevant.\n\nWrite at least 150 words.", "model_answer": "The bar chart illustrates the proportion of adults using the internet on a daily basis across five age categories in 2010 and 2020.\n\nOverall, internet usage increased significantly across all age groups over the decade, with younger demographics maintaining higher usage rates throughout both years.\n\nIn 2010, the 18-24 age group had the highest daily internet usage at 75%, followed by the 25-34 group at 68%. Usage declined progressively with age, with the 35-44 bracket at 52%, the 45-54 group at 38%, and those aged 55 and over showing the lowest usage at just 22%.\n\nBy 2020, all categories experienced substantial growth. The youngest group reached near-universal adoption at 98%, while the 25-34 demographic rose to 95%. Notably, the older age groups showed the most dramatic improvements: the 55+ category nearly tripled their usage to 61%, and the 45-54 group more than doubled to 79%. The 35-44 age bracket also increased considerably to 88%.\n\nThe data reveals that while the digital divide between age groups persisted, it narrowed considerably over the ten-year period.", "teacher_notes": "Review the response against the relevant four Writing criteria. The model is one possible response, not the only answer and not a certified band. Check claims, organisation, language and task coverage separately.", "chart": {"kind": "grouped_bar", "unit": "%", "x_label": "Age group", "y_label": "Adults using the internet daily (%)", "categories": ["18–24", "25–34", "35–44", "45–54", "55+"], "series": [{"label": "2010", "values": [75, 68, 52, 38, 22]}, {"label": "2020", "values": [98, 95, 88, 79, 61]}], "source": "Fictional data supplied for this practice task; not a real survey"}, "authorship": "Brains Heist AI-assisted revision; human review pending", "model_word_count": 173, "sources": []}, "changes": ["Replaced text bars with a structured, renderable grouped chart and accessible data table", "Normalized task number, test type, word minimum and timing units", "Model clearly labelled as an example, without a band claim"], "blockers": ["Human editorial/key review", "Source and reuse-rights review", "Originality and exposure-family review", "Delivery and scoped pilot checks"], "material_type": "ielts_writing_task", "material_id": "13", "source_snapshot": {"id": 13, "slug": "internet-usage-graph", "title": "Internet Usage by Age Group", "prompt": "The bar chart below shows the percentage of adults who used the internet daily in five different age groups in 2010 and 2020.\r\n\r\nSummarize the information by selecting and reporting the main features, and make comparisons where relevant.\r\n\r\nWrite at least 150 words.\r\n\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\nDAILY INTERNET USAGE BY AGE GROUP (%)\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\n\r\nAge Group    │  2010   │  2020\r\n─────────────┼─────────┼─────────\r\n18-24        │   75%   │   98%\r\n25-34        │   68%   │   95%\r\n35-44        │   52%   │   88%\r\n45-54        │   38%   │   79%\r\n55+          │   22%   │   61%\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\n\r\nBar Chart Visualization:\r\n\r\n18-24:  2010 ███████████████████████████████ 75%\r\n        2020 ███████████████████████████████████████████████████ 98%\r\n\r\n25-34:  2010 ████████████████████████████ 68%\r\n        2020 ██████████████████████████████████████████████████ 95%\r\n\r\n35-44:  2010 █████████████████████ 52%\r\n        2020 █████████████████████████████████████████████ 88%\r\n\r\n45-54:  2010 ████████████████ 38%\r\n        2020 █████████████████████████████████████████ 79%\r\n\r\n55+:    2010 █████████ 22%\r\n        2020 ████████████████████████████████ 61%", "is_active": true, "task_type": "Task 1 Academic", "created_at": "2025-12-03T06:12:19.711253+00:00", "bands_target": "7.0", "display_code": "W-006", "required_tier": "prime_prep_user", "sample_answer": "The bar chart illustrates the proportion of adults using the internet on a daily basis across five age categories in 2010 and 2020.\r\n\r\nOverall, internet usage increased significantly across all age groups over the decade, with younger demographics maintaining higher usage rates throughout both years.\r\n\r\nIn 2010, the 18-24 age group had the highest daily internet usage at 75%, followed by the 25-34 group at 68%. Usage declined progressively with age, with the 35-44 bracket at 52%, the 45-54 group at 38%, and those aged 55 and over showing the lowest usage at just 22%.\r\n\r\nBy 2020, all categories experienced substantial growth. The youngest group reached near-universal adoption at 98%, while the 25-34 demographic rose to 95%. Notably, the older age groups showed the most dramatic improvements: the 55+ category nearly tripled their usage to 61%, and the 45-54 group more than doubled to 79%. The 35-44 age bracket also increased considerably to 88%.\r\n\r\nThe data reveals that while the digital divide between age groups persisted, it narrowed considerably over the ten-year period.", "originality_label": null}, "review_status": "pending_human_review", "human_approval": null, "revision_sha256": "52dfdf5e5bc23fc72f0617a691145c6f1b8406ebdbc151e277756bb3d1aa4f77"}$payload$::jsonb; begin
