do $seed$ declare source jsonb; candidate jsonb:=$payload${"code": "W-008", "disposition": "revise", "revision": "2026-10-15.1", "content": {"skill": "writing", "title": "Complaint Letter to Restaurant", "scope": "Writing practice; example response is not a band guarantee", "test_type": "general_training", "task_number": 1, "minimum_words": 150, "suggested_minutes": 20, "prompt": "You recently had dinner at a restaurant and were unhappy with the service.\n\nWrite a letter to the restaurant manager. In your letter:\n- Say when you visited and what problems you had\n- Describe how the staff dealt with your complaints\n- Suggest what the manager should do\n\nWrite at least 150 words.\nYou do NOT need to write any addresses.\nBegin your letter as follows: Dear Sir or Madam,", "model_answer": "Dear Sir or Madam,\n\nI am writing to express my disappointment regarding my dining experience at your restaurant on Saturday, 15th November. My family and I visited to celebrate my mother's birthday, but unfortunately, the evening did not meet our expectations.\n\nFirstly, despite having a reservation for 7 PM, we were kept waiting for 30 minutes before being seated. Once at our table, we waited an additional 20 minutes before a waiter took our order. When the food finally arrived, two of the four dishes were cold, and my steak was overcooked despite requesting it medium-rare.\n\nWhen I raised these issues with the waiter, he seemed dismissive and offered no apology or solution. He simply shrugged and said the kitchen was busy. No manager was available to speak with us.\n\nI would suggest that you review your staff training procedures, particularly regarding customer service and handling complaints. Additionally, implementing better communication between front-of-house and kitchen staff might prevent such issues.\n\nI look forward to hearing from you regarding how you intend to address these concerns.\n\nYours faithfully,\n[Your name]", "teacher_notes": "Review the response against the relevant four Writing criteria. The model is one possible response, not the only answer and not a certified band. Check claims, organisation, language and task coverage separately.", "authorship": "Brains Heist AI-assisted revision; human review pending", "model_word_count": 179, "sources": []}, "changes": ["Clearly separated General Training letter practice from Academic tasks", "Normalized task number, test type, word minimum and timing units", "Model clearly labelled as an example, without a band claim"], "blockers": ["Human editorial/key review", "Source and reuse-rights review", "Originality and exposure-family review", "Delivery and scoped pilot checks"], "material_type": "ielts_writing_task", "material_id": "15", "source_snapshot": {"id": 15, "slug": "complaint-letter", "title": "Complaint Letter to Restaurant", "prompt": "You recently had dinner at a restaurant and were unhappy with the service.\r\n\r\nWrite a letter to the restaurant manager. In your letter:\r\n- Say when you visited and what problems you had\r\n- Describe how the staff dealt with your complaints\r\n- Suggest what the manager should do\r\n\r\nWrite at least 150 words.\r\nYou do NOT need to write any addresses.\r\nBegin your letter as follows: Dear Sir or Madam,", "is_active": true, "task_type": "Task 1 General", "created_at": "2025-12-03T06:12:19.711253+00:00", "bands_target": "7.0", "display_code": "W-008", "required_tier": "prime_prep_user", "sample_answer": "Dear Sir or Madam,\r\n\r\nI am writing to express my disappointment regarding my dining experience at your restaurant on Saturday, 15th November. My family and I visited to celebrate my mother's birthday, but unfortunately, the evening did not meet our expectations.\r\n\r\nFirstly, despite having a reservation for 7 PM, we were kept waiting for 30 minutes before being seated. Once at our table, we waited an additional 20 minutes before a waiter took our order. When the food finally arrived, two of the four dishes were cold, and my steak was overcooked despite requesting it medium-rare.\r\n\r\nWhen I raised these issues with the waiter, he seemed dismissive and offered no apology or solution. He simply shrugged and said the kitchen was busy. No manager was available to speak with us.\r\n\r\nI would suggest that you review your staff training procedures, particularly regarding customer service and handling complaints. Additionally, implementing better communication between front-of-house and kitchen staff might prevent such issues.\r\n\r\nI look forward to hearing from you regarding how you intend to address these concerns.\r\n\r\nYours faithfully,\r\n[Your name]", "originality_label": null}, "review_status": "pending_human_review", "human_approval": null, "revision_sha256": "8c3575df9fa35954edf4de2b3ba5a75641d5bcf0373358317b8053248d27f9f6"}$payload$::jsonb; begin
