do $seed$ declare source jsonb; candidate jsonb:=$payload${"code": "W-009", "disposition": "revise", "revision": "2026-10-15.1", "content": {"skill": "writing", "title": "Population Changes in Three Cities", "scope": "Writing practice; example response is not a band guarantee", "test_type": "academic", "task_number": 1, "minimum_words": 150, "suggested_minutes": 20, "prompt": "The bar chart below shows population changes in three cities between 2000 and 2020.\n\nSummarize the information by selecting and reporting the main features, and make comparisons where relevant.\n\nWrite at least 150 words.", "model_answer": "The bar chart illustrates population trends in three cities—Metro City, Riverside, and Oldtown—over a twenty-year period from 2000 to 2020.\n\nOverall, while Metro City experienced substantial population growth, Oldtown showed a consistent decline, and Riverside remained relatively stable throughout the period.\n\nIn 2000, Oldtown had the largest population at 3.5 million, followed by Metro City with 2.1 million and Riverside with 1.8 million. However, this ranking changed dramatically over the following two decades.\n\nMetro City demonstrated the most remarkable growth, more than doubling its population from 2.1 million to 5.2 million by 2020. This represents an increase of approximately 148%. In contrast, Oldtown experienced steady decline, falling from 3.5 million to 2.8 million, a decrease of 20%.\n\nRiverside showed minimal change, with its population fluctuating slightly between 1.8 and 2.0 million throughout the period, ending at 1.9 million in 2020.\n\nBy 2020, Metro City had become the most populous of the three cities, overtaking Oldtown which had held that position in 2000.", "teacher_notes": "Review the response against the relevant four Writing criteria. The model is one possible response, not the only answer and not a certified band. Check claims, organisation, language and task coverage separately.", "chart": {"kind": "grouped_bar", "unit": "millions", "x_label": "City", "y_label": "Population (millions)", "categories": ["Metro City", "Riverside", "Oldtown"], "series": [{"label": "2000", "values": [2.1, 1.8, 3.5]}, {"label": "2010", "values": [3.4, 2, 3.2]}, {"label": "2020", "values": [5.2, 1.9, 2.8]}], "source": "Fictional data supplied for this practice task; not a real demographic dataset"}, "authorship": "Brains Heist AI-assisted revision; human review pending", "model_word_count": 174, "sources": []}, "changes": ["Retained the fuller population task as the consolidation candidate", "Replaced text bars with a structured, renderable grouped chart and accessible data table", "Normalized task number, test type, word minimum and timing units", "Model clearly labelled as an example, without a band claim"], "blockers": ["Human editorial/key review", "Source and reuse-rights review", "Originality and exposure-family review", "Delivery and scoped pilot checks"], "material_type": "ielts_writing_task", "material_id": "17", "source_snapshot": {"id": 17, "slug": "population-changes-cities", "title": "Population Changes in Three Cities", "prompt": "The bar chart below shows population changes in three cities between 2000 and 2020.\r\n\r\nSummarize the information by selecting and reporting the main features, and make comparisons where relevant.\r\n\r\nWrite at least 150 words.\r\n\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\nPOPULATION OF THREE CITIES (in millions)\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\n\r\nCity          │  2000   │  2010   │  2020\r\n──────────────┼─────────┼─────────┼─────────\r\nMetro City    │   2.1   │   3.4   │   5.2\r\nRiverside     │   1.8   │   2.0   │   1.9\r\nOldtown       │   3.5   │   3.2   │   2.8\r\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\n\r\nBar Chart Visualization:\r\n\r\nMetro City:  2000 ████████████ 2.1M\r\n             2010 ████████████████████ 3.4M\r\n             2020 ██████████████████████████████ 5.2M\r\n\r\nRiverside:   2000 ██████████ 1.8M\r\n             2010 ███████████ 2.0M\r\n             2020 ██████████ 1.9M\r\n\r\nOldtown:     2000 ████████████████████ 3.5M\r\n             2010 ██████████████████ 3.2M\r\n             2020 ████████████████ 2.8M", "is_active": true, "task_type": "Task 1 Academic", "created_at": "2025-12-03T06:19:45.617266+00:00", "bands_target": "7.0", "display_code": "W-009", "required_tier": "free", "sample_answer": "The bar chart illustrates population trends in three cities—Metro City, Riverside, and Oldtown—over a twenty-year period from 2000 to 2020.\r\n\r\nOverall, while Metro City experienced substantial population growth, Oldtown showed a consistent decline, and Riverside remained relatively stable throughout the period.\r\n\r\nIn 2000, Oldtown had the largest population at 3.5 million, followed by Metro City with 2.1 million and Riverside with 1.8 million. However, this ranking changed dramatically over the following two decades.\r\n\r\nMetro City demonstrated the most remarkable growth, more than doubling its population from 2.1 million to 5.2 million by 2020. This represents an increase of approximately 148%. In contrast, Oldtown experienced steady decline, falling from 3.5 million to 2.8 million, a decrease of 20%.\r\n\r\nRiverside showed minimal change, with its population fluctuating slightly between 1.8 and 2.0 million throughout the period, ending at 1.9 million in 2020.\r\n\r\nBy 2020, Metro City had become the most populous of the three cities, overtaking Oldtown which had held that position in 2000.", "originality_label": null}, "review_status": "pending_human_review", "human_approval": null, "revision_sha256": "256bf083371cd4de493595bb53fe5e3ffe22a7ba2a1bab25dd1703c4c3aabee4"}$payload$::jsonb; begin
if not exists(select 1 from private.ielts_practice_material_holds where material_type='ielts_writing_task' and material_id='17') then raise exception 'expected_legacy_hold_missing';end if;
