create or replace function public.rpc_ielts_content_list() returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 perform private.ielts_cleanup_authorize();
 return (with sources as (
 select to_jsonb(s) r,'reading' skill,'ielts_reading_set' kind,s.is_active and exists(select 1 from public.ielts_reading_questions q where q.set_id=s.id) complete from public.ielts_reading_sets s
 union all select to_jsonb(s),'listening','ielts_listening_set',s.is_active and nullif(trim(s.audio_url),'') is not null and exists(select 1 from public.ielts_listening_questions q where q.set_id=s.id) from public.ielts_listening_sets s
 union all select to_jsonb(s),'writing','ielts_writing_task',s.is_active from public.ielts_writing_tasks s
 union all select to_jsonb(s),'speaking','ielts_speaking_task',s.is_active from public.ielts_speaking_tasks s
 ), data as (
 select r->>'id' id,coalesce(r->>'title',r->>'slug','Speaking Part '||(r->>'part')) title,skill,r->'is_active' is_active,coalesce(r->>'level',r->>'task_type',case when skill='speaking' then 'part '||(r->>'part') end) difficulty,r->'est_band_min' band_min,r->'est_band_max' band_max,r->'created_at' created_at,r->>'display_code' display_code,
 exists(select 1 from private.ielts_legacy_cleanup_versions v where v.material_type=kind and v.material_id=r->>'id') frozen_legacy,
 complete and private.ielts_practice_material_allowed(kind,r->>'id') and private.ielts_originality_label(kind,r->>'id') is not null ready_to_assign,
 case when exists(select 1 from private.ielts_practice_material_holds h where h.material_type=kind and h.material_id=r->>'id') then jsonb_build_array((select h.reason from private.ielts_practice_material_holds h where h.material_type=kind and h.material_id=r->>'id'))
 when not complete then '["Incomplete or inactive material"]'::jsonb
 when not private.ielts_practice_material_allowed(kind,r->>'id') then '["Protected assessment material cannot be assigned as practice"]'::jsonb
 when private.ielts_originality_label(kind,r->>'id') is null then '["Originality review required"]'::jsonb else '[]'::jsonb end warnings from sources
 )select coalesce(jsonb_agg(to_jsonb(data) order by skill,display_code,id),'[]') from data);
end; $$;
revoke all on function public.rpc_ielts_content_list() from public,anon,authenticated,service_role;
grant execute on function public.rpc_ielts_content_list() to authenticated;
create function private.ielts_preserve_legacy_source() returns trigger language plpgsql security definer set search_path='' as $$
declare kind text; old_id text; new_id text;
begin
 kind:=case tg_table_name when 'ielts_reading_questions' then 'ielts_reading_set' when 'ielts_listening_questions' then 'ielts_listening_set' else left(tg_table_name,-1) end;
 if tg_op<>'INSERT' then old_id:=case when tg_table_name like '%_questions' then to_jsonb(old)->>'set_id' else to_jsonb(old)->>'id' end;end if;
 if tg_op<>'DELETE' then new_id:=case when tg_table_name like '%_questions' then to_jsonb(new)->>'set_id' else to_jsonb(new)->>'id' end;end if;
 if exists(select 1 from private.ielts_legacy_cleanup_versions where material_type=kind and material_id in (old_id,new_id)) then raise exception 'Legacy source is frozen to preserve history. Use its corrected review candidate and a new material identity after approval.';end if;
 if tg_op='DELETE' then return old;end if;return new;
end; $$;
revoke all on function private.ielts_preserve_legacy_source() from public,anon,authenticated,service_role;
create trigger preserve_legacy_source before insert or update or delete on public.ielts_reading_sets for each row execute function private.ielts_preserve_legacy_source();
create trigger preserve_legacy_source before insert or update or delete on public.ielts_listening_sets for each row execute function private.ielts_preserve_legacy_source();
create trigger preserve_legacy_source before insert or update or delete on public.ielts_writing_tasks for each row execute function private.ielts_preserve_legacy_source();
create trigger preserve_legacy_source before insert or update or delete on public.ielts_speaking_tasks for each row execute function private.ielts_preserve_legacy_source();
create trigger preserve_legacy_source before insert or update or delete on public.ielts_reading_questions for each row execute function private.ielts_preserve_legacy_source();
create trigger preserve_legacy_source before insert or update or delete on public.ielts_listening_questions for each row execute function private.ielts_preserve_legacy_source();
